import {lessons,escapeHTML as esc} from './learning.js';
import {books,curriculum} from './curriculum.js';
import {schoolSources} from './school-data.js';
import {labDefinitions} from './lab-science.js';
import {createNotebook} from './notebook.js';
const levelNames={basic:'Cơ bản',apply:'Vận dụng',advanced:'Mở rộng'};
export function createPages(api){
 let filter='all',level='all',noteTab='notes';const notebook=createNotebook({...api,lessons}),state=()=>api.getState();
 function renderTopics(){const s=state(),c=curriculum[s.grade],source=schoolSources[s.grade],all=lessons.filter(l=>l.grade===s.grade),list=all.filter(l=>(filter==='all'||(filter==='interactive')===Boolean(l.activity||l.lab||labDefinitions.some(d=>d.lesson===l.id)))&&(level==='all'||l.level===level));document.querySelector('#book-select').value=s.book;
 document.querySelector('#curriculum-overview').innerHTML=`<article class="curriculum-card"><div class="curriculum-heading"><div><span class="eyebrow">${s.grade<10?'THCS / KHOA HỌC TỰ NHIÊN':'THPT / SINH HỌC'} ${s.grade}</span><h3>${c.name}</h3><p>${c.subtitle}</p></div><span class="curriculum-symbol">${api.icon(c.icon)}</span></div><ol class="curriculum-topics">${source.topics.map((t,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span>${t}</li>`).join('')}</ol><div class="curriculum-card-footer"><p>${s.book==='kntt'?`Đối chiếu SGK ${source.title} · Kết nối tri thức · NXBGDVN.`:'Bài viết hiện đối chiếu chi tiết với SGK Kết nối tri thức. Nguồn CTST được liên kết để tham khảo, không gán số bài tương đương giữa hai bộ.'}</p><button class="text-button" data-action="sources">SGK & nguồn đã đối chiếu ${api.icon('external')}</button></div></article>`;
 document.querySelector('#lesson-count').textContent=`${list.length} / ${all.length} bài đã biên soạn`;
 document.querySelector('#topic-grid').innerHTML=(list.length?list.map((l,i)=>`<article class="topic-card ${i===0?'featured':''}"><div class="topic-image">${l.image?`<img src="assets/${l.image}" alt="Minh họa chủ đề ${esc(l.title)}" loading="lazy">`:`<div class="topic-illustration illustration-${l.visual}">${api.icon(l.icon)}</div>`}<span class="topic-type">${api.icon(l.icon)} ${l.type}</span><button class="bookmark-button ${s.saved.includes(l.id)?'saved':''}" data-action="bookmark" data-id="${l.id}" aria-label="${s.saved.includes(l.id)?'Bỏ lưu':'Lưu'} bài ${l.title}" aria-pressed="${s.saved.includes(l.id)}">${api.icon('bookmark')}</button>${s.completed.includes(l.id)?`<span class="lesson-done">${api.icon('check')} Đã khám phá</span>`:''}</div><div class="topic-body"><span class="topic-kicker">${l.kicker}</span><span class="lesson-level level-${l.level}">${levelNames[l.level]}</span><h3>${l.title}</h3><p>${l.description}</p><div class="topic-bottom"><span>${api.icon('clock')} ${l.minutes} phút</span><button data-action="lesson" data-id="${l.id}">Khám phá ${api.icon('arrow-up-right')}</button></div></div></article>`).join(''):'<p class="campus-empty">Chưa có bài thuộc lựa chọn này. Thử đổi mức độ hoặc cách khám phá.</p>')+(filter==='all'&&level==='all'?`<article class="topic-card field-mission-card"><div class="topic-image"><img src="assets/forest.jpg" alt="Một khu rừng để bắt đầu quan sát" loading="lazy"><span class="topic-type">${api.icon('leaf')} TỪ TRANG SÁCH RA ĐỜI SỐNG</span></div><div class="topic-body"><span class="topic-kicker">HỌC BẰNG MỘT CÂU HỎI</span><h3>Mang điều vừa hiểu ra thế giới.</h3><p>Sinh học quanh ta, BioMap và nhiệm vụ dựa trên bằng chứng.</p><div class="topic-bottom"><a href="#/world">Thế giới sống →</a><a href="#/quests">BioQuest ↗</a></div></div></article>`:'');api.updateProgress();
 }
 function renderNotebook(tab=noteTab){noteTab=tab;notebook.render(tab)}
 function openNotebook(tab=noteTab){notebook.flush();api.closeDialog();api.navigate('notebook');renderNotebook(tab);api.updateProgress()}
 function enrichLesson(l){const s=state(),source=schoolSources[l.grade],lab=labDefinitions.find(d=>d.id===l.lab||d.lesson===l.id),copy=document.querySelector('.lesson-copy');copy.insertAdjacentHTML('afterbegin',`<div class="lesson-structure"><span>01 · Khởi động</span><span>02 · Khám phá</span><span>03 · Minh họa</span><span>04 · Kiểm tra</span><span>05 · Vận dụng</span><span>06 · Kết nối</span></div><div class="lesson-start-question"><span class="campus-kicker">TỪ MỘT CÂU HỎI</span><p>${esc(l.description)}</p></div>`);if(l.image)document.querySelector('.lesson-callout').insertAdjacentHTML('beforebegin',`<figure class="lesson-evidence-image"><img src="assets/${l.image}" alt="Minh họa ${esc(l.title)}"><figcaption>Hình minh họa · Không sao chép từ SGK.</figcaption></figure>`);
 if(lab&&!l.activity)document.querySelector('.lesson-callout').insertAdjacentHTML('afterend',`<button class="button button-dark" data-action="experiment" data-id="${lab.id}">${api.icon(lab.icon)} Thử trong BioLab</button>`);if(l.grade===8&&l.id.includes('breathing'))copy.insertAdjacentHTML('beforeend','<a href="#/lab/human" class="button button-dark">Quan sát một nhịp thở trong Human Lab →</a>');
 copy.insertAdjacentHTML('beforeend',`<section class="lesson-application"><span class="campus-kicker">05 / VẬN DỤNG & GIỮ LẠI ĐIỀU HIỂU</span><h3>Thử giải thích bằng lời của bạn.</h3><p>${esc(l.application||l.wonder)}</p><textarea id="lesson-application-note" rows="3" maxlength="1600" placeholder="Tôi quan sát… Tôi giải thích… Tôi còn muốn kiểm tra…" aria-label="Ghi chép vận dụng bài học"></textarea><button type="button" class="button button-dark" data-save-application="${l.id}">Giữ suy nghĩ vào sổ tay</button><div class="lesson-next-links"><a href="#/world">Đối chiếu với đời sống ↗</a><a href="#/quests">Vận dụng trong BioQuest ↗</a></div></section>`);
 document.querySelector('.lesson-source').innerHTML=`<strong>SGK đã đối chiếu:</strong> <a href="${source.url}" target="_blank" rel="noopener">${source.kind} ${source.title} · Kết nối tri thức · NXBGDVN ↗</a><br>Nội dung VNScape biên soạn riêng theo chủ đề, không sao chép trang sách. ${l.referenceSource&&l.referenceSource!==source.url?`<a href="${l.referenceSource}" target="_blank" rel="noopener">Nguồn khoa học bổ sung ↗</a>`:''}${s.book==='ctst'?'<br>CTST: chưa xác nhận tương đương từng bài.':''}`;
 }
 function openSources(){api.showDialog('Khoa học cần có nguồn.','NXBGDVN / NGUỒN HỌC LIỆU ĐÃ ĐỐI CHIẾU',`<p class="dialog-lead">${lessons.length} bài khám phá từ lớp 6–12, biên soạn riêng và đối chiếu SGK Kết nối tri thức trên cổng sách điện tử NXBGDVN. Chưa phải toàn bộ nội dung mọi bộ sách.</p><div class="book-source-grid">${Object.entries(schoolSources).map(([g,b])=>`<article class="book-source-card"><span class="eyebrow">${Number(g)<10?'THCS':'THPT'} / LỚP ${g}</span><h3>${b.title}</h3><p>${b.topics.join(' · ')}</p><a href="${b.url}" target="_blank" rel="noopener">${b.kind} · Kết nối tri thức · NXBGDVN ↗</a>${b.guideUrl?`<a href="${b.guideUrl}" target="_blank" rel="noopener">SGV đối chiếu thêm ↗</a>`:''}<small>Đối chiếu nguồn: 06/11/2026</small></article>`).join('')}</div><div class="teacher-note">Đã đọc nội dung và mục lục SGK tại các nguồn trên. Mức Cơ bản/Vận dụng/Mở rộng và câu hỏi do VNScape tổ chức; chưa khẳng định sản phẩm được NXBGDVN kiểm định hoặc chứng nhận.</div><h3 class="source-section-title">Chân trời sáng tạo</h3><p>Tham khảo thông tin chính thức; không gán số bài của Kết nối tri thức sang CTST khi chưa đối chiếu chi tiết.</p><ul class="sources-list">${[10,11,12].map(g=>`<li><a href="${books.ctst.sources[g]}" target="_blank" rel="noopener">Thông tin NXBGDVN · CTST lớp ${g} ↗</a></li>`).join('')}</ul><details class="asset-credits"><summary>Hình ảnh, mô hình & nguồn bổ sung</summary><p>Ảnh thiên nhiên Unsplash; SVG và mô hình Three.js dựng riêng với màu quy ước. BioMap và BioLab có nguồn cùng giới hạn tại từng hồ sơ. Phông Be Vietnam Pro và Lora lưu cùng dự án.</p></details>`,'sources')}
 document.querySelector('#learning-filter').addEventListener('change',e=>{filter=e.target.value;renderTopics()});document.querySelector('#learning-level').addEventListener('change',e=>{level=e.target.value;renderTopics()});document.querySelector('#book-select').addEventListener('change',e=>{state().book=e.target.value==='ctst'?'ctst':'kntt';api.persist();renderTopics()});document.addEventListener('click',e=>{const b=e.target.closest('[data-save-application]');if(!b)return;const l=lessons.find(l=>l.id===b.dataset.saveApplication),value=document.querySelector('#lesson-application-note')?.value.trim();if(!l||!value){api.toast('Viết một quan sát hoặc cách giải thích trước khi lưu.');return}api.addNote(`Vận dụng: ${l.title}`,value+`\n\nĐối chiếu SGK: ${schoolSources[l.grade].url}`);api.toast('Đã giữ suy nghĩ vận dụng vào sổ tay.')});
 return {renderTopics,renderNotebook,openNotebook,enrichLesson,openSources,flushNotebook:()=>notebook.flush()};
}
